Пустая строка — существующее значение String, поэтому ?? её не заменяет. Контракт обозначает отсутствие через nil; возвращаем nil для неизвестного id.

protocol PlaybackSettings {
    var rate: Double { get set }
}
struct AudioSettings: PlaybackSettings {
    var rate = 1.0
}
var settings: any PlaybackSettings = AudioSettings()
settings.rate = 1.5
print(settings.rate)

get set обещает запись, поэтому rate в реализации и settings как хранилище структуры объявлены var. Консоль выводит 1.5.

protocol TranscriptSource {
    var label: String { get }
    func text(for trackID: Int) -> String?
}
struct DownloadedTranscriptSource: TranscriptSource {
    let label = "На устройстве"
    let texts = [1: "Первый урок"]
    func text(for trackID: Int) -> String? { texts[trackID] }
}
struct DemoTranscriptSource: TranscriptSource {
    let label = "Демо"
    func text(for trackID: Int) -> String? {
        trackID == 1 ? "Короткий пример" : nil
    }
}
func transcriptText(source: any TranscriptSource, trackID: Int) -> String {
    "\(source.label): \(source.text(for: trackID) ?? "Недоступно")"
}
print(transcriptText(source: DownloadedTranscriptSource(), trackID: 1))
print(transcriptText(source: DemoTranscriptSource(), trackID: 1))
print(transcriptText(source: DemoTranscriptSource(), trackID: 9))

Обе реализации соответствуют одному контракту, общая функция не знает их устройство. Вывод: «На устройстве: Первый урок», «Демо: Короткий пример», «Демо: Недоступно».
